<script setup lang="ts">
import ExpenseSourcePanel from'./ExpenseSourcePanel.vue';import{qualityExpenseEntry,type QualityExpenseEntry}from'./quality-source-entry';import{useSalesScope}from'./use-sales-scope';
import QuarterReportWorkspace from './QuarterReportWorkspace.vue';
import QuarterDeliveryEvidence from './QuarterDeliveryEvidence.vue';
import{ref,watch,onMounted}from'vue';import{Plus,X,ArrowLeft,Calculator,ClipboardCheck,CheckCircle2,FileText}from'@lucide/vue';
const reportRef=ref<any>(null),expensesLoaded=ref(false);
const props=defineProps<{staff:any;sourceEntry?:QualityExpenseEntry|null}>(),emit=defineEmits(['unauthorized','return-quality']);const now=new Date(Date.now()+8*3600000),prev=new Date(Date.UTC(now.getUTCFullYear(),Math.floor(now.getUTCMonth()/3)*3-1,1));
const functions=ref<string[]>([]),clinics=ref<any[]>([]),clinic=ref(''),year=ref(prev.getUTCFullYear()),quarter=ref(Math.floor(prev.getUTCMonth()/3)+1),policies=ref<any[]>([]),section=ref('quarters'),rows=ref<any[]>([]),expenses=ref<any[]>([]),detail=ref<any>(null),preparation=ref<any>(null),result=ref<any>(null),candidates=ref<any[]>([]),basis=ref<any>(null),preview=ref<any>(null),mode=ref(''),form=ref<any>({}),confirmed=ref(false),pending=ref<any>(null),busy=ref(false),loading=ref(false),ready=ref(false),error=ref(''),notice=ref('');
const has=(f:string)=>functions.value.includes(f),short=(s:string)=>s.slice(0,8).toUpperCase(),full=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'尚未正式确认',stateName=(s:string)=>({pending_review:'待总部复核',returned:'已退回',confirmed:'已正式确认'}[s]||s),kindName=(s:string)=>({receipt:'治疗实收',sale:'商品实收',issue:'材料成本',expense:'运营费用'}[s]||s);
const doctorName=(id:string)=>detail.value?.doctors.find((d:any)=>d.doctorId===id)?.name||short(id),clinicName=(id:string)=>clinics.value.find(c=>c.id===id)?.name||short(id);
const locatedExpenseRef=ref<any>(null),sourceEpoch=ref(0),identity=()=>JSON.stringify([props.staff.accountId,props.staff.employeeId]),authScope=useSalesScope(identity),sourceScope=useSalesScope(()=>JSON.stringify([identity(),clinic.value,year.value,quarter.value,section.value,props.sourceEntry]));
async function openLocatedExpense(value:any){if(busy.value||loading.value||pending.value||mode.value||!has('expense.manage')||!locatedExpenseRef.value?.isCurrent(value))return;const expense=JSON.parse(JSON.stringify(value)),current=sourceScope.begin('edit',()=>String(sourceEpoch.value));loading.value=true;error.value='';try{const b=has('quarter.read')?await request(''):{items:[]};if(!current()||!locatedExpenseRef.value?.isCurrent(expense))return;rows.value=b.items;await open('expense',expense);}catch(e){if(current())error.value=explain(e);}finally{if(current.active())loading.value=false;}}
function returnQuality(){if(busy.value||loading.value||pending.value||mode.value||!props.sourceEntry)return;emit('return-quality');}
function expenseAccessLost(){expenses.value=[];expensesLoaded.value=false;functions.value=functions.value.filter(f=>f!=='expense.manage');if(!pending.value){mode.value='';form.value={};}error.value='当前费用读取权限已失效，请重新核对。';}
watch(identity,()=>{locatedExpenseRef.value=null;sourceEpoch.value++;functions.value=[];clinics.value=[];clinic.value='';rows.value=[];expenses.value=[];expensesLoaded.value=false;detail.value=null;preparation.value=null;result.value=null;candidates.value=[];basis.value=null;preview.value=null;mode.value='';form.value={};pending.value=null;busy.value=false;loading.value=false;ready.value=false;section.value='quarters';void initialize();},{flush:'sync'});
watch(()=>JSON.stringify([identity(),clinic.value,year.value,quarter.value,section.value,props.sourceEntry]),()=>{loading.value=false;},{flush:'sync'});
class ApiError extends Error{constructor(public status:number,m:string){super(m);}}
async function request(path:string,body?:any){const own=authScope.capture(),a=new AbortController(),t=setTimeout(()=>a.abort(),15000);try{const r=await fetch('/api/v1/quarter'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:a.signal});const b=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401&&own())emit('unauthorized');throw new ApiError(r.status,b.message||'请求失败。');}return b;}finally{clearTimeout(t);}}
const explain=(e:unknown)=>e instanceof Error?e.message:'操作失败。';
async function initialize(){const current=authScope.begin('initialize');loading.value=true;try{const raw=JSON.parse(sessionStorage.getItem('adc.quarterPending:'+props.staff.accountId)||'null');if(raw&&typeof raw.body?.requestId==='string'&&/^(|\/expenses|\/[0-9a-f-]{36}\/(submissions|results|adjustment)|\/results\/[0-9a-f-]{36}\/review)$/.test(raw.path))pending.value=raw;const b=await request('/bootstrap');if(!current())return;functions.value=b.functions;clinics.value=b.clinics;const target=props.sourceEntry?qualityExpenseEntry(props.sourceEntry):null;if(target&&!b.clinics.some((c:any)=>c.id===target.clinicId))throw Error('当前季度资料范围不包含原费用诊所。');clinic.value=target?.clinicId||b.clinics[0]?.id||'';policies.value=b.policies;ready.value=true;if(target){year.value=target.year;quarter.value=target.quarter;section.value='expenses';}else await refresh();}catch(e){if(current())error.value=explain(e);}finally{if(current())loading.value=false;}}
async function refresh(){if(section.value==='reports'&&reportRef.value)return reportRef.value.refresh();if(!ready.value)return initialize();const current=sourceScope.begin('refresh');loading.value=true;error.value='';if(section.value==='expenses'){expenses.value=[];expensesLoaded.value=false;}try{const list=await request('');if(!current())return;rows.value=list.items;if(has('expense.manage')&&clinic.value){const data=await request('/expenses?clinicId='+clinic.value+'&year='+year.value+'&quarter='+quarter.value);if(!current())return;expenses.value=data.items;expensesLoaded.value=true;}const resultId=result.value?.result.result_id;if(detail.value)await select(detail.value.quarter.quarter_id);if(current()&&resultId)await readResult(resultId);}catch(e){if(current()){if(e instanceof ApiError&&e.status===403)expenseAccessLost();else error.value=explain(e);}}finally{if(current.active())loading.value=false;}}
async function select(id:string){const current=sourceScope.begin('detail');try{const data=await request('/'+id);if(!current())return;detail.value=data;if(!data.scopes.some((s:any)=>s.clinicId===clinic.value))clinic.value=data.scopes[0]?.clinicId||'';preparation.value=null;result.value=null;}catch(e){if(current()){error.value=explain(e);detail.value=null;}}}
async function prepare(){if(!detail.value)return;loading.value=true;error.value='';try{preparation.value=await request('/'+detail.value.quarter.quarter_id+'/prepare?clinicId='+clinic.value);}catch(e){error.value=explain(e);preparation.value=null;}finally{loading.value=false;}}
async function readResult(id:string){try{result.value=await request('/results/'+id);}catch(e){error.value=explain(e);result.value=null;}}
function close(){if(busy.value||pending.value)return;mode.value='';preview.value=null;}
async function loadCandidates(){try{candidates.value=(await request('/candidates?year='+year.value+'&quarter='+quarter.value)).clinics;}catch(e){error.value=explain(e);candidates.value=[];}}
async function open(m:string,p?:any){if(pending.value){error.value='请先核实原提交。';return;}error.value='';confirmed.value=false;preview.value=null;
 if(m==='create'){await loadCandidates();form.value={selected:candidates.value.map(c=>c.id),scopeConfirmed:false};}
 if(m==='expense')form.value={id:p?.expense_id||null,version:Number(p?.row_version)||0,category:p?.category||'',amount:p?.amount||'',occurredOn:p?.occurred_on||'',voucherReference:p?.voucher_reference||'',voucherNote:p?.voucher_note||'',pendingNote:p?.pending_note||'',actualConfirmed:false,distinctConfirmed:false,reason:'',adjustmentIds:[]};
 if(m==='submit'){if(!preparation.value)await prepare();if(!preparation.value)return;form.value={completenessConfirmed:false,emptyConfirmed:false,evidence:'',note:''};}
 if(m==='calculate'){try{basis.value=await request('/'+detail.value.quarter.quarter_id+'/basis');form.value={policyId:policies.value[0]?.policy_version_id||'',sources:basis.value.sources.map((s:any)=>({...s,allocations:[{doctorId:'',amount:'',basis:''}]})),reason:''};}catch(e){error.value=explain(e);return;}}
 if(m==='adjustment')form.value={reason:'',explicitDecision:false};
 if(m==='review')form.value={decision:p,opinion:'',explicitDecision:false};mode.value=m;
}
watch(form,()=>{preview.value=null;confirmed.value=false;},{deep:true});
function calcBody(){return{...(detail.value.adjustments?.active?{adjustmentId:detail.value.adjustments.active.id}:{}),basisToken:basis.value.token,policyId:form.value.policyId,allocations:form.value.sources.flatMap((s:any)=>s.allocations.map((a:any)=>({kind:s.kind,sourceId:s.id,doctorId:a.doctorId==='clinic'?null:a.doctorId,amount:a.amount,basis:a.basis})))};}
async function trial(){busy.value=true;error.value='';try{preview.value=await request('/'+detail.value.quarter.quarter_id+'/preview',calcBody());}catch(e){error.value=explain(e);}finally{busy.value=false;}}
async function send(path:string,body:any,label:string){const own=authScope.capture(),originalKey='adc.quarterPending:'+props.staff.accountId,p={path,body,label};busy.value=true;error.value='';notice.value='';try{sessionStorage.setItem(originalKey,JSON.stringify(p));const r=await request(path,body);if(!own())return;sessionStorage.removeItem(originalKey);pending.value=null;mode.value='';preview.value=null;notice.value=r.repeated?'已核实原提交，未重复记账、计算或确认。':r.existing?'已找到同一原范围、提交或结果，未重复办理。':label;try{const qid=r.quarterId||(!path?r.id:null);if(qid)await select(qid);await refresh();if(!own())return;if(path==='/expenses')await locatedExpenseRef.value?.refresh();if(r.resultId&&has('quarter.result.read'))await readResult(r.resultId);}catch(e){error.value='保存已确认，请刷新查看。'+explain(e);}}catch(e){if(!(e instanceof ApiError)||e.status>=500||e.status===401){pending.value=p;error.value='提交结果暂不能确认，请用原账号核实原提交，不要另记费用或重复核算。';}else{sessionStorage.removeItem(originalKey);pending.value=null;error.value=explain(e);}}finally{if(own())busy.value=false;}}
async function save(){const f=form.value,id=crypto.randomUUID(),qid=detail.value?.quarter.quarter_id;try{
 if(mode.value==='create')return await send('',{requestId:id,year:year.value,quarter:quarter.value,scopes:candidates.value.filter(c=>f.selected.includes(c.id)).map(c=>({clinicId:c.id,doctorIds:c.doctors.map((d:any)=>d.id)})),scopeConfirmed:f.scopeConfirmed},'季度原范围已建立，尚未提交、计算或确认。');
 if(mode.value==='expense')return await send('/expenses',{...f,requestId:id,clinicId:clinic.value},'真实费用资料及原版已保存；这不是支付或已完成分摊。');
 if(mode.value==='submit')return await send('/'+qid+'/submissions',{...f,...(detail.value.adjustments?.active?{adjustmentId:detail.value.adjustments.active.id}:{}),requestId:id,clinicId:clinic.value,sourceToken:preparation.value.token},'本诊所固定来源提交版已保存，仍须财务核算及总部复核。');
 if(mode.value==='calculate'){if(!preview.value)return await trial();if(!confirmed.value)return;return await send('/'+qid+'/results',{...calcBody(),requestId:id,previewToken:preview.value.token,reason:f.reason||null},'整批核算结果已保存为待复核，尚未正式确认。');}
 if(mode.value==='adjustment')return await send('/'+qid+'/adjustment',{requestId:id,baseResultId:detail.value.adjustments.latestConfirmedResultId,reason:f.reason,explicitDecision:f.explicitDecision},'已记录本次调整事项；旧确认结果和首次确认时间保持，各诊所须重新核实本轮资料。');
 if(mode.value==='review')return await send('/results/'+result.value.result.result_id+'/review',{...f,requestId:id,reviewToken:result.value.reviewToken},f.decision==='confirm'?'本版已正式确认全部原范围；确认信息与快照已保存，既有首次确认时刻保持。':'本版已退回，原结果保留，财务须另版核对。');
 }catch(e){error.value=explain(e);}}
defineExpose({refresh});onMounted(initialize);
</script>

<template><div class="q-workspace"><div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert success" role="status">{{notice}}</div><div v-if="pending" class="b-alert warning">有结果待核实的原提交。<button class="b-button" :disabled="busy" @click="send(pending.path,pending.body,pending.label)">核实原提交</button></div>
 <div class="f-tabs"><button :class="{active:section==='quarters'}" @click="section='quarters'">季度资料与业绩</button><button v-if="has('quarter.result.read')" :class="{active:section==='reports'}" @click="section='reports'">查询与导出</button><button v-if="has('expense.manage')" :class="{active:section==='expenses'}" @click="section='expenses'">运营费用</button></div><p v-if="loading" class="b-help">正在核对当前来源及版本…</p>
 <QuarterReportWorkspace v-if="section==='reports'" ref="reportRef" :staff="staff" @unauthorized="emit('unauthorized')"/><template v-else-if="section==='expenses'"><ExpenseSourcePanel v-if="has('expense.manage')" ref="locatedExpenseRef" :staff="staff" :clinic-id="clinic" :year="year" :quarter="quarter" :entry="sourceEntry" :blocked="busy||loading||!!pending||!!mode" @context-change="sourceEpoch++" @edit="openLocatedExpense" @unauthorized="emit('unauthorized')" @access-lost="expenseAccessLost" @return-quality="returnQuality"/><section v-else-if="sourceEntry" class="b-card q-block"><p>当前费用读取权限不可用，原资料问题仍需核查。</p><button class="b-button outline" :disabled="busy||loading||!!pending||!!mode" @click="returnQuality">返回原资料问题</button></section><div class="q-filter"><label>费用诊所<select v-model="clinic" :disabled="busy||loading||!!pending||!!mode" @change="refresh"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>年份<input v-model.number="year" :disabled="busy||loading||!!pending||!!mode" type="number" min="2020" max="2100" @change="refresh"/></label><label>季度<select v-model.number="quarter" :disabled="busy||loading||!!pending||!!mode" @change="refresh"><option v-for="i in 4" :key="i" :value="i">第{{i}}季度</option></select></label><button class="b-button" :disabled="busy||!!pending" @click="open('expense')"><Plus :size="16"/>登记费用</button></div><section class="b-card q-block"><h2>运营费用资料</h2><p>费用登记不代表支付，也不表示公共费用已经分配给牙医。</p><article v-for="e in expenses" :key="e.expense_id" class="q-row"><div><strong>{{e.category}} · ¥{{e.amount}}</strong><p>{{e.occurred_on}} · 凭据 {{e.voucher_reference||'待补'}}</p><small>{{e.pending_note||e.voucher_note||'无待补事项'}} · 第{{e.row_version}}版</small></div><button class="b-button outline small" :disabled="busy||!!pending" @click="open('expense',e)">核实更正</button></article><p v-if="expensesLoaded&&!expenses.length&&!loading" class="b-empty">所选期间暂无费用记录；仍需管理人员核对完整性，不自动认定费用为零。</p><p v-if="!expensesLoaded&&!loading" class="b-help">当前未读取期间费用列表，可先按编号定位；点击刷新或调整期间条件后查询列表。</p></section></template>
 <template v-else-if="!detail"><div class="q-section-head"><div><h2>季度核算</h2><p>原范围固定，来源先提交，整批结果再复核。</p></div><button v-if="has('quarter.create')" class="b-button" :disabled="busy||!!pending" @click="open('create')"><Plus :size="16"/>启动季度核算</button></div><article v-for="q in rows" :key="q.quarter_id" class="b-card q-block q-row"><div><div class="b-eyebrow">QUARTER PERFORMANCE</div><h2>{{q.quarter_label}}</h2><p>首次全部范围确认：{{full(q.first_full_confirmed_at)}}</p><span class="b-pill" :class="q.first_full_confirmed_at?'active':''">{{q.first_full_confirmed_at?'已有正式确认':'准备 / 核算中'}}</span></div><button class="b-button outline" @click="select(q.quarter_id)">查看季度</button></article><section v-if="!rows.length&&!loading" class="b-card b-empty q-block"><Calculator :size="30"/><strong>暂无已启动的核算季度</strong><span>由有权财务明确季度和原范围后启动。</span></section></template>
 <template v-else><button class="f-text q-back" @click="detail=null;result=null;preparation=null"><ArrowLeft :size="16"/>返回季度列表</button><section class="b-card q-block"><div class="q-section-head"><div><div class="b-eyebrow">{{detail.quarter.business_timezone}}</div><h2>{{detail.quarter.quarter_label}} · 原纳入范围</h2><p>{{full(detail.quarter.quarter_start_at)}} 至 {{full(detail.quarter.quarter_end_at)}}，右端不含</p></div><span class="b-pill" :class="detail.quarter.first_full_confirmed_at?'active':''">{{detail.quarter.first_full_confirmed_at?'已有正式确认':'尚未全范围确认'}}</span></div><div v-for="s in detail.scopes" :key="s.clinicId" class="q-scope"><strong>{{s.name}}</strong><p>{{detail.doctors.filter((d:any)=>d.clinicId===s.clinicId).map((d:any)=>d.name).join('、')}}</p><small>{{detail.submissions.find((x:any)=>x.clinic_id===s.clinicId)?'已提交第'+detail.submissions.find((x:any)=>x.clinic_id===s.clinicId).version_no+'版':'尚未提交本店资料'}}</small></div><p class="b-help">首次全部范围正式确认：{{full(detail.quarter.first_full_confirmed_at)}}。原纳入范围不因后续查询筛选而缩小。</p></section>
 <section v-if="detail.quarter.first_full_confirmed_at" class="b-card q-block"><div class="q-section-head"><div><h2>确认后的调整事项</h2><p>保留原确认快照，按原全部范围重新提交、核算和复核。</p></div><button v-if="has('quarter.review')&&!detail.adjustments?.active" class="b-button outline" :disabled="busy||!!pending" @click="open('adjustment')">记录调整事项</button></div><div v-if="detail.adjustments?.active" class="q-scope"><strong>{{detail.adjustments.active.status==='pending_review'?'调整版待总部复核':'本轮调整待补正及重新提交'}}</strong><p>{{detail.adjustments.active.reason}}</p><small>{{detail.adjustments.active.openedBy}} · {{full(detail.adjustments.active.openedAt)}} · 基于结果 {{short(detail.adjustments.active.baseResultId)}}</small></div><p v-else>当前没有进行中的调整。最新已确认结果：{{short(detail.adjustments.latestConfirmedResultId)}}</p><details v-if="detail.adjustments?.rounds.length"><summary>查看历次调整事项</summary><article v-for="a in detail.adjustments.rounds" :key="a.id" class="q-source"><strong>{{a.status==='confirmed'?'调整已重新确认':a.status==='pending_review'?'待复核':a.status==='open'?'进行中':'已有后续版本'}}</strong><p>{{a.reason}}</p><small>{{a.openedBy}} · {{full(a.openedAt)}}</small></article></details></section><section v-if="!result" class="b-card q-block"><div class="q-section-head"><div><h2>诊所资料准备</h2><p>核对现有实收、领用和费用，不重复录另一套交易。</p></div><button class="b-button outline" :disabled="busy" @click="prepare"><FileText :size="16"/>核对来源</button></div><label>查看本店范围<select v-model="clinic" @change="preparation=null"><option v-for="s in detail.scopes" :key="s.clinicId" :value="s.clinicId">{{s.name}}</option></select></label><template v-if="preparation"><div v-if="preparation.blockers.length" class="b-alert warning"><strong>关键事项尚待核实</strong><ul><li v-for="b in preparation.blockers" :key="b">{{b}}</li></ul></div><p v-else class="b-help">本次未发现已记录来源的关键缺项，仍须人工核对资料是否完整。</p><div class="q-table-wrap"><table><thead><tr><th>来源 / 原版</th><th>实际发生</th><th>金额</th></tr></thead><tbody><tr v-for="s in preparation.sources" :key="s.kind+s.id"><td><strong>{{s.label}}</strong><small>{{short(s.id)}} · 原版{{s.version}}</small></td><td>{{s.kind==='expense'?s.at:full(s.at)}}</td><td>{{s.amount===null?'待核实':'¥ '+s.amount}}</td></tr></tbody></table></div><QuarterDeliveryEvidence :clinics="detail.scopes" :items="preparation.deliveryEvidence||[]"/><p v-if="!preparation.sources.length" class="b-help">本次没有查到计金额来源，须明确核实是否漏登。交付依据另列，不因交付推算收入或成本。</p><button v-if="has('quarter.submit')" class="b-button" :disabled="busy||!!pending||(!!detail.quarter.first_full_confirmed_at&&!detail.adjustments?.active)||preparation.blockers.length>0" @click="open('submit')">核实并提交本店来源版</button></template></section>
 <section v-if="has('quarter.result.read')&&!result" class="b-card q-block"><div class="q-section-head"><div><h2>整批核算与总部复核</h2><p>财务逐笔核实归属和分配，计算完成仍是待复核。</p></div><button v-if="has('quarter.calculate')" class="b-button" :disabled="busy||!!pending||(!!detail.quarter.first_full_confirmed_at&&!detail.adjustments?.active)" @click="open('calculate')"><Calculator :size="16"/>核对并试算</button></div><article v-for="r in detail.results" :key="r.result_id" class="q-row"><div><strong>整批第{{r.version_no}}版{{r.result_id===detail.adjustments?.latestConfirmedResultId?' · 最新已确认':r.result_id===detail.quarter.first_confirmed_result_id?' · 首次确认原版':''}}</strong><p>{{stateName(r.review_state)}} · 计算 {{full(r.calculated_at)}}</p></div><button class="b-button outline small" @click="readResult(r.result_id)">查看依据 / 复核</button></article><p v-if="!detail.results.length" class="b-help">还没有整批结果版。</p></section>
 <template v-if="result"><button class="f-text q-back" @click="result=null"><ArrowLeft :size="16"/>返回资料与结果列表</button><section class="b-card q-block"><div class="q-section-head"><div><h2>整批第{{result.result.version_no}}版{{result.plan.adjustmentId?' · 调整版':''}}</h2><p v-if="result.result.change_reason">本版原因：{{result.result.change_reason}}</p><p>{{stateName(result.result.review_state)}} · 计算 {{full(result.result.calculated_at)}}</p></div><span class="b-pill" :class="result.result.review_state==='confirmed'?'active':''">{{stateName(result.result.review_state)}}</span></div><div v-if="result.stale" class="b-alert warning">{{result.result.review_state==='confirmed'?'这是按当时来源保存的已确认历史版。后续更正不会重算本版，请结合调整记录及最新结果查看。':'当前来源或提交已变化，本待复核版不能直接确认，请先退回并重新核对。'}}</div><div class="q-table-wrap"><table><thead><tr><th>牙医 / 诊所</th><th>实收收入</th><th>材料成本</th><th>分配费用</th><th>经营贡献</th></tr></thead><tbody><tr v-for="l in result.plan.lines" :key="l.clinicId+l.doctorId"><td><strong>{{doctorName(l.doctorId)}}</strong><small>{{clinicName(l.clinicId)}}</small></td><td>{{l.income}}</td><td>{{l.cost}}</td><td>{{l.expense}}</td><td><strong>{{l.contribution}}</strong></td></tr></tbody></table></div><p class="b-help">单位：元。经营贡献＝实收收入−材料成本−分配运营费用，不是工资或个人激励。</p><p v-for="u in result.plan.unassigned" :key="u.sourceId" class="q-unassigned">未归属牙医的诊所商品实收：¥{{u.amount}} · 来源 {{short(u.sourceId)}}</p><details><summary>查看本版逐来源归集与核实依据</summary><article v-for="(a,k) in result.plan.allocations" :key="k" class="q-source"><strong>{{kindName(a.kind)}} {{short(a.sourceId)}} · ¥{{a.amount}}</strong><p>{{a.doctorId?doctorName(a.doctorId):'保留为诊所商品收入'}} · {{a.basis}}</p></article><p v-if="!result.plan.allocations.length" class="b-help">本版来源集合为空，各诊所已明确核实合理零业务；原提交及依据保留。</p></details><div v-for="(r,k) in result.reviews" :key="k" class="q-review-note"><strong>{{r.decision==='confirm'?'总部正式确认':'总部退回'}} · {{full(r.reviewed_at)}}</strong><p>{{r.conclusion}}</p></div><div v-if="has('quarter.review')&&result.result.review_state==='pending_review'" class="q-actions"><button class="b-button outline" :disabled="busy||!!pending" @click="open('review','return')">退回财务核对</button><button class="b-button" :disabled="busy||!!pending||result.stale" @click="open('review','confirm')"><CheckCircle2 :size="17"/>确认全部原范围</button></div></section></template></template>
 <QuarterDeliveryEvidence :clinics="detail.scopes" v-if="result" :items="result.plan.basis.clinics.flatMap((s:any)=>s.deliveryEvidence||[])"/><div v-if="mode" class="b-backdrop"><form class="b-dialog q-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button class="b-close" type="button" aria-label="关闭季度办理" :disabled="busy||!!pending" @click="close"><X :size="21"/></button><div class="b-eyebrow">QUARTER PERFORMANCE</div><h2>{{mode==='create'?'核对季度原范围':mode==='expense'?'登记 / 核实更正费用':mode==='submit'?'确认本诊所来源提交':mode==='calculate'?'逐来源归属与费用分配':mode==='adjustment'?'记录已确认结果的调整事项':form.decision==='confirm'?'总部正式确认':'退回财务核对'}}</h2><div v-if="error" class="b-alert error" role="alert">{{error}}</div>
 <template v-if="mode==='create'"><div class="b-two-fields"><label>核算年份<input type="number" v-model.number="year" min="2020" max="2100" required @change="loadCandidates();form.selected=[]"/></label><label>自然季度<select v-model.number="quarter" @change="loadCandidates();form.selected=[]"><option v-for="i in 4" :key="i" :value="i">第{{i}}季度</option></select></label></div><article v-for="c in candidates" :key="c.id" class="q-scope"><label class="b-checkbox"><input v-model="form.selected" type="checkbox" :value="c.id"/><span>{{c.name}}</span></label><p>{{c.doctors.map((d:any)=>d.name).join('、')||'无可核对牙医范围，不能纳入'}}</p></article><label class="b-checkbox"><input type="checkbox" v-model="form.scopeConfirmed" required/><span>已核对本季原纳入诊所和完整牙医集合，建立后不通过删范围绕过核算。</span></label></template>
 <template v-if="mode==='expense'"><div class="f-context">{{clinicName(clinic)}} · 费用登记不代表支付或已分摊。</div><label>实际费用类别<input v-model="form.category" required maxlength="150"/></label><div class="b-two-fields"><label>金额（元）<input v-model="form.amount" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" required/></label><label>实际发生日期<input v-model="form.occurredOn" type="date" required/></label></div><label>凭据编号及可追查来源定位<input v-model="form.voucherReference" maxlength="2000"/></label><label>凭据来源说明<textarea v-model="form.voucherNote" rows="2" maxlength="2000"/></label><label>待补或待核实事项<textarea v-model="form.pendingNote" :required="!form.voucherReference" rows="2" maxlength="2000"/></label><div v-if="rows.some(q=>q.adjustment)" class="q-scope"><strong>涉及已确认季度时，明确选择本次费用所需的调整轮次</strong><p class="b-help">仅选择原或新发生日期涉及的季度。跨季更正可能需要两季分别记录调整事项，普通写入不会解除闭季保护。</p><label v-for="q in rows.filter(q=>q.adjustment)" :key="q.quarter_id" class="b-checkbox"><input type="checkbox" v-model="form.adjustmentIds" :value="q.adjustment.id"/><span>{{q.quarter_label}} · {{q.adjustment.reason}}</span></label></div><label v-if="form.id||form.adjustmentIds.length">更正或补录实际依据与调整原因<textarea v-model="form.reason" required rows="2" maxlength="2000"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.distinctConfirmed"/><span>如有相同凭据，已核实这是另一笔真实费用，不是重复录入。</span></label><label class="b-checkbox"><input type="checkbox" v-model="form.actualConfirmed" required/><span>已核实真实费用、诊所、金额和发生日期，资料不齐处已明确待补。</span></label></template>
 <template v-if="mode==='submit'"><div class="f-context">{{detail.quarter.quarter_label}} · {{clinicName(clinic)}} · {{preparation.sources.length}}笔来源</div><label>完整性核实依据<textarea v-model="form.evidence" required rows="3" maxlength="2000"/></label><label>保留的非关键事项（可空）<textarea v-model="form.note" rows="2" maxlength="2000"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.completenessConfirmed" required/><span>已组织核对本店实际业务与本次来源集合，关键交易、价格和资料问题已核实。</span></label><label v-if="!preparation.sources.length" class="b-checkbox"><input type="checkbox" v-model="form.emptyConfirmed" required/><span>已核实本季没有可计金额来源，已排除漏登实收、领用成本或费用；交付核对依据另列。</span></label><p class="b-help">提交保存本次来源原版及未解决事项，不代表财务算完或总部确认。</p></template>
 <template v-if="mode==='calculate'&&basis"><QuarterDeliveryEvidence :clinics="detail.scopes" :items="basis.clinics.flatMap((s:any)=>s.deliveryEvidence||[])"/><div v-if="basis.blockers.length" class="b-alert warning"><strong>不能生成可确认结果</strong><ul><li v-for="b in basis.blockers" :key="b">{{b}}</li></ul></div><label>采用核算口径<select v-model="form.policyId" required><option v-for="p in policies" :key="p.policy_version_id" :value="p.policy_version_id">第{{p.version_no}}版 · 实收收入 / 核实领用成本 / 人工费用分配</option></select></label><p class="b-help">按每笔来源的实际归属填写金额和依据。公共费用不猜比例，商品没有明确牙医归属时留诊所。</p><article v-for="s in form.sources" :key="s.kind+s.id" class="q-edit-source"><strong>{{s.label}} · {{s.amount===null?'金额待核实':'¥'+s.amount}}</strong><p>{{clinicName(s.clinicId)}} · {{short(s.id)}} · 原版{{s.version}}</p><div v-for="(a,k) in s.allocations" :key="k" class="q-allocation"><div class="b-two-fields"><label>核实归属<select v-model="a.doctorId" required><option value="">请明确核实归属</option><option v-if="s.kind==='sale'" value="clinic">未明确牙医归属，留诊所商品收入</option><option v-for="d in detail.doctors.filter((d:any)=>d.clinicId===s.clinicId)" :key="d.doctorId" :value="d.doctorId">{{d.name}}</option></select></label><label>本项归集金额（元）<input v-model="a.amount" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" required/></label></div><label>逐来源核实 / 分配依据<textarea v-model="a.basis" required rows="2" maxlength="1500"/></label><button v-if="s.allocations.length>1" type="button" class="f-text" @click="s.allocations.splice(k,1)">移除此未保存分配</button></div><button type="button" class="b-button outline small" @click="s.allocations.push({doctorId:'',amount:'',basis:''})"><Plus :size="14"/>增加本来源分配</button></article><p v-if="!form.sources.length" class="b-help">原范围全部诊所已明确提交合理零业务时，可以保留完整牙医分项的零值结果；未提交不能计算。</p><label v-if="detail.results.length">新版本核实 / 调整原因<textarea v-model="form.reason" required rows="2" maxlength="2000"/></label><div v-if="preview" class="q-trial"><h3>整批试算，尚未保存或确认</h3><div v-for="l in preview.lines" :key="l.clinicId+l.doctorId" class="q-trial-row"><strong>{{doctorName(l.doctorId)}} · {{clinicName(l.clinicId)}}</strong><p>实收{{l.income}} − 材料{{l.cost}} − 费用{{l.expense}} = 经营贡献{{l.contribution}}元</p></div><p v-for="u in preview.unassigned" :key="u.sourceId">诊所商品实收保留：{{u.amount}}元</p><label class="b-checkbox"><input type="checkbox" v-model="confirmed" required/><span>已核对全部原范围、来源和分配，保存为待总部复核版。</span></label></div></template>
 <template v-if="mode==='adjustment'"><p class="b-help">针对当前最新已确认结果记录具体问题。原范围与首次确认时间保持，财务补正后仍须各店重新提交和总部再次复核。</p><label>发现的问题及调整原因<textarea v-model="form.reason" required rows="4" maxlength="2000"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.explicitDecision" required/><span>明确记录本轮调整事项，保留原确认结果，不通过缩小范围或直接覆盖结果处理。</span></label></template><template v-if="mode==='review'"><div class="f-context">{{detail.quarter.quarter_label}} · 整批第{{result.result.version_no}}版 · {{form.decision==='confirm'?'确认全部原范围':'退回并终结本版'}}</div><label>总部复核意见<textarea v-model="form.opinion" required rows="4" maxlength="2000"/></label><label class="b-checkbox"><input type="checkbox" v-model="form.explicitDecision" required/><span>{{form.decision==='confirm'?'已查阅全部原范围、逐来源依据及问题，明确同意正式确认。':'明确退回本版，要求财务按意见另版核对，原版和意见保留。'}}</span></label><p class="b-help">系统保存时会再次检查范围、关键问题和新增/更正来源；首次确认记入完成时刻，后续调整另存本版复核时间并保留首次时刻。</p></template>
 <button v-if="pending" type="button" class="b-button full" :disabled="busy" @click="send(pending.path,pending.body,pending.label)">核实原提交</button><button v-else class="b-button full" :disabled="busy||(mode==='calculate'&&basis?.blockers.length>0)||(mode==='create'&&!form.selected.length)">{{busy?'正在核对保存…':mode==='calculate'?(preview?'保存整批待复核版':'核对并计算试算'):mode==='adjustment'?'确认记录本轮调整事项':mode==='review'?(form.decision==='confirm'?'正式确认全部原范围':'确认退回财务'):mode==='submit'?'确认保存本店提交版':mode==='create'?'确认启动并固定原范围':'确认保存真实费用资料'}}</button>
 </form></div></div></template>





